define('LANG_CSP_HINTS', ['default-src' => 'Die Direktive default-src legt die Sicherheitsrichtlinie für Inhaltstypen fest, für die keine eigene Direktive definiert ist.', 'script-src' => 'Die Direktive script-src legt zulässige Quellen für JavaScript fest. Wenn sie nicht angegeben ist, gilt default-src. Ist script-src oder default-src vorhanden, werden Inline-Skripte und eval() blockiert, sofern nicht jeweils Unsafe Inline und Unsafe Eval hinzugefügt werden.', 'script-src-elem' => 'Die Direktive script-src-elem legt zulässige Quellen für JavaScript in Skriptelementen fest (Skriptanfragen und Skriptblöcke). Wenn sie nicht angegeben ist, gilt script-src (und damit default-src). Ist sie vorhanden, werden Inline-Skripte und eval() blockiert, sofern nicht jeweils Unsafe Inline und Unsafe Eval hinzugefügt werden.', 'script-src-attr' => 'Die Direktive script-src-attr legt zulässige JavaScript-Quellen in Attributen wie eingebetteten Ereignisbehandlern fest. Wenn sie nicht angegeben ist, gilt script-src (und damit default-src). Ist sie vorhanden, werden Inline-Skripte und eval() blockiert, sofern nicht jeweils Unsafe Inline und Unsafe Eval hinzugefügt werden.', 'style-src' => 'Die Direktive style-src legt zulässige Quellen für Stylesheets fest. Wenn sie nicht angegeben ist, gilt default-src. Ist style-src oder default-src vorhanden, sind eingebettete <style>-Elemente und HTML-Styleattribute verboten, sofern Unsafe Inline nicht zugelassen wird.', 'style-src-elem' => 'Die Direktive style-src-elem legt zulässige Quellen für Stylesheets fest, ausgenommen in Attributen definierte Styles. Wenn sie nicht angegeben ist, gilt style-src (und damit default-src). Ist sie vorhanden, sind eingebettete <style>-Elemente und HTML-Styleattribute deaktiviert, sofern Unsafe Inline nicht zugelassen wird.', 'style-src-attr' => 'Die Direktive style-src-attr legt zulässige Quellen für Styles in Inline-Attributen fest. Wenn sie nicht angegeben ist, gilt style-src (und damit default-src). Ist sie vorhanden, sind eingebettete <style>-Elemente und HTML-Styleattribute deaktiviert, sofern Unsafe Inline nicht zugelassen wird.', 'img-src' => 'Die Direktive img-src legt zulässige Quellen für Bilder und Favicons fest. Wenn sie nicht angegeben ist, gilt default-src.', 'font-src' => 'Die Direktive font-src legt zulässige Quellen für Schriftarten fest, die mit @font-face geladen werden. Wenn sie nicht angegeben ist, gilt default-src.', 'connect-src' => 'Die Direktive connect-src legt zulässige Quellen für fetch-, XMLHttpRequest-, WebSocket- und EventSource-Verbindungen fest. Wenn sie nicht angegeben ist, gilt default-src.', 'media-src' => 'Die Direktive media-src legt zulässige Quellen für <audio>- und <video>-Elemente fest. Wenn sie nicht angegeben ist, gilt default-src.', 'object-src' => 'Die Direktive object-src legt zulässige Quellen für <object>-, <embed>- und <applet>-Elemente fest. Wenn sie nicht angegeben ist, gilt default-src.', 'child-src' => 'Die Direktive child-src legt zulässige Quellen für Elemente wie <frame> und <iframe> fest. Wenn sie nicht angegeben ist, gilt default-src.', 'frame-src' => 'Die Direktive frame-src legt zulässige Quellen für Elemente wie <frame> und <iframe> fest. Wenn sie nicht angegeben ist, gilt child-src (und damit default-src).', 'worker-src' => 'Die Direktive worker-src legt zulässige Quellen für Worker, SharedWorker oder ServiceWorker fest. Wenn sie nicht angegeben ist, gilt default-src.', 'frame-ancestors' => 'Die Direktive frame-ancestors legt fest, welche übergeordneten Seiten diese Seite mit Elementen wie <frame> und <iframe> einbetten dürfen. Sie ersetzt den Header X-Frame-Options.', 'form-action' => 'Die Direktive form-action legt fest, welche URLs zum Senden von <form>-Elementen verwendet werden dürfen.', 'manifest-src' => 'Die Direktive manifest-src legt fest, welches Manifest auf die Ressource angewendet werden darf. Wenn sie nicht angegeben ist, gilt default-src.']);
